create table if not exists role (id bigint not null auto_increment comment 'role primary key', code varchar(128) not null comment 'role code', name varchar(128) not null comment 'role name', status varchar(32) not null default 'ACTIVE' comment 'status', primary key(id), unique key uk_role_code(code)) engine=InnoDB default charset=utf8mb4 comment='role';
create table if not exists resource (id bigint not null auto_increment comment 'resource primary key', code varchar(128) not null comment 'resource code', permission_code varchar(160) not null comment 'permission code', name varchar(128) not null comment 'resource name', resource_type varchar(32) not null comment 'resource type', primary key(id), unique key uk_resource_code(code), unique key uk_permission_code(permission_code)) engine=InnoDB default charset=utf8mb4 comment='resource';
create table if not exists role_resource (id bigint not null auto_increment comment 'grant primary key', role_id bigint not null comment 'role id', resource_id bigint not null comment 'resource id', effect varchar(16) not null comment 'ALLOW or DENY', primary key(id)) engine=InnoDB default charset=utf8mb4 comment='role resource grant';
create table if not exists subject_role_assignment (id bigint not null auto_increment comment 'assignment primary key', subject_type varchar(32) not null comment 'subject type', subject_id bigint not null comment 'subject id', role_id bigint not null comment 'role id', primary key(id)) engine=InnoDB default charset=utf8mb4 comment='subject role assignment';

